-- ShopPro 知识库和文件上传系统扩展表\n-- 在01_init_database.sql基础上添加的补充表\n-- 创建时间: 2025-01-19\n\nUSE shoppro_db;\n\n-- 文件上传记录表（补充表，用于记录所有上传的文件）\nCREATE TABLE IF NOT EXISTS file_uploads (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键ID',\n    original_file_name VARCHAR(255) NOT NULL COMMENT '原始文件名',\n    saved_file_name VARCHAR(500) NOT NULL COMMENT '保存的文件名（含路径）',\n    file_url VARCHAR(500) NOT NULL COMMENT '文件访问URL',\n    file_size BIGINT NOT NULL COMMENT '文件大小（字节）',\n    mime_type VARCHAR(100) COMMENT '文件MIME类型',\n    file_extension VARCHAR(20) COMMENT '文件扩展名',\n    related_entity_type VARCHAR(50) COMMENT '关联实体类型（如knowledge、customer等）',\n    related_entity_id BIGINT COMMENT '关联实体ID',\n    uploaded_by BIGINT COMMENT '上传人ID',\n    uploaded_by_name VARCHAR(100) COMMENT '上传人用户名',\n    status TINYINT DEFAULT 1 COMMENT '文件状态：1-有效，0-已删除',\n    md5_hash VARCHAR(32) COMMENT 'MD5哈希值（用于重复检测）',\n    download_count INT DEFAULT 0 COMMENT '下载次数',\n    remarks TEXT COMMENT '备注/描述',\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',\n    \n    INDEX idx_entity (related_entity_type, related_entity_id),\n    INDEX idx_uploader (uploaded_by),\n    INDEX idx_status (status),\n    INDEX idx_md5 (md5_hash),\n    INDEX idx_created_at (created_at),\n    FOREIGN KEY (uploaded_by) REFERENCES users(id) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件上传记录表';\n\n-- 知识库访问日志表（用于分析热门内容）\nCREATE TABLE IF NOT EXISTS knowledge_access_logs (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键ID',\n    knowledge_id BIGINT NOT NULL COMMENT '知识库ID',\n    user_id BIGINT COMMENT '访问用户ID',\n    access_ip VARCHAR(45) COMMENT '访问IP地址',\n    user_agent TEXT COMMENT '用户代理',\n    referer VARCHAR(500) COMMENT '来源页面',\n    access_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '访问时间',\n    \n    INDEX idx_knowledge (knowledge_id),\n    INDEX idx_user (user_id),\n    INDEX idx_access_time (access_time),\n    FOREIGN KEY (knowledge_id) REFERENCES knowledge_base(id) ON DELETE CASCADE,\n    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库访问日志表';\n\n-- 知识库评论表（支持用户评论和反馈）\nCREATE TABLE IF NOT EXISTS knowledge_comments (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键ID',\n    knowledge_id BIGINT NOT NULL COMMENT '知识库ID',\n    user_id BIGINT COMMENT '评论用户ID',\n    user_name VARCHAR(100) COMMENT '评论用户名',\n    content TEXT NOT NULL COMMENT '评论内容',\n    rating INT COMMENT '评分（1-5）',\n    helpful_count INT DEFAULT 0 COMMENT '有帮助数',\n    parent_comment_id BIGINT COMMENT '父评论ID（支持回复）',\n    status TINYINT DEFAULT 1 COMMENT '状态：1-显示，0-隐藏（审核中）',\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',\n    \n    INDEX idx_knowledge (knowledge_id),\n    INDEX idx_user (user_id),\n    INDEX idx_status (status),\n    INDEX idx_created_at (created_at),\n    FOREIGN KEY (knowledge_id) REFERENCES knowledge_base(id) ON DELETE CASCADE,\n    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,\n    FOREIGN KEY (parent_comment_id) REFERENCES knowledge_comments(id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库评论表';\n\n-- 知识库标签表（用于更好的分类和搜索）\nCREATE TABLE IF NOT EXISTS knowledge_tags (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键ID',\n    tag_name VARCHAR(100) NOT NULL UNIQUE COMMENT '标签名称',\n    tag_count INT DEFAULT 0 COMMENT '使用次数',\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',\n    \n    INDEX idx_tag_name (tag_name),\n    INDEX idx_tag_count (tag_count)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库标签表';\n\n-- 知识库关联表（用于关联相关知识）\nCREATE TABLE IF NOT EXISTS knowledge_relations (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键ID',\n    knowledge_id BIGINT NOT NULL COMMENT '主知识库ID',\n    related_knowledge_id BIGINT NOT NULL COMMENT '关联的知识库ID',\n    relation_type VARCHAR(50) COMMENT '关系类型（如：related、referenced_by等）',\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',\n    \n    UNIQUE INDEX unique_relation (knowledge_id, related_knowledge_id),\n    INDEX idx_related_knowledge (related_knowledge_id),\n    FOREIGN KEY (knowledge_id) REFERENCES knowledge_base(id) ON DELETE CASCADE,\n    FOREIGN KEY (related_knowledge_id) REFERENCES knowledge_base(id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库关联表';\n\n-- 添加对知识库的FULLTEXT索引支持中文（需要分词插件支持）\n-- 如果配置了中文分词插件，可以使用以下方式改进搜索\nALTER TABLE knowledge_base ADD FULLTEXT INDEX ft_title_content (title, content) WITH PARSER ngram;\n"